import React, { useState } from 'react';

// Goldfish avatar options - simple colored fish emojis with backgrounds
const AVATARS = [
  { id: 'red', color: 'from-red-400 to-red-600', emoji: '🐠', label: 'Ruby' },
  { id: 'blue', color: 'from-blue-400 to-blue-600', emoji: '🐟', label: 'Sapphire' },
  { id: 'green', color: 'from-green-400 to-green-600', emoji: '🐡', label: 'Emerald' },
  { id: 'yellow', color: 'from-yellow-400 to-amber-500', emoji: '🐠', label: 'Gold' },
];

const PlayerSetupModal = ({ isOpen, onClose, onComplete }) => {
  const [playerName, setPlayerName] = useState('');
  const [selectedAvatar, setSelectedAvatar] = useState(null);
  const [error, setError] = useState('');

  if (!isOpen) return null;

  const handleContinue = () => {
    if (!playerName.trim()) {
      setError('Please enter your name');
      return;
    }
    if (!selectedAvatar) {
      setError('Please select an avatar');
      return;
    }
    onComplete({ name: playerName.trim(), avatar: selectedAvatar });
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 animate-fadeIn">
      <div className="bg-gradient-to-b from-blue-800 to-blue-900 rounded-2xl p-6 max-w-md w-full mx-4 shadow-2xl border border-blue-500/30">
        <h2 className="text-2xl font-bold text-white mb-2 text-center">
          Welcome, Player!
        </h2>
        <p className="text-blue-200 text-center text-sm mb-6">
          Set up your profile before playing
        </p>

        {/* Name Input */}
        <div className="mb-6">
          <label className="block text-white text-sm font-medium mb-2">
            Your Name
          </label>
          <input
            type="text"
            value={playerName}
            onChange={(e) => {
              setPlayerName(e.target.value);
              setError('');
            }}
            placeholder="Enter your name..."
            maxLength={12}
            className="w-full px-4 py-3 bg-blue-950/50 border border-blue-500/30 rounded-xl text-white placeholder-blue-300/50 focus:outline-none focus:ring-2 focus:ring-orange-400 transition-all"
          />
        </div>

        {/* Avatar Selection */}
        <div className="mb-6">
          <label className="block text-white text-sm font-medium mb-3">
            Choose Your Fish
          </label>
          <div className="grid grid-cols-4 gap-3">
            {AVATARS.map((avatar) => (
              <button
                key={avatar.id}
                onClick={() => {
                  setSelectedAvatar(avatar);
                  setError('');
                }}
                className={`flex flex-col items-center p-3 rounded-xl transition-all duration-200 ${
                  selectedAvatar?.id === avatar.id
                    ? 'ring-4 ring-orange-400 scale-110 bg-gradient-to-br ' + avatar.color
                    : 'bg-blue-950/50 hover:bg-blue-900/50 border border-blue-500/30 hover:scale-105'
                }`}
              >
                <span className="text-3xl mb-1">{avatar.emoji}</span>
                <span className={`text-xs font-medium ${selectedAvatar?.id === avatar.id ? 'text-white' : 'text-blue-200'}`}>
                  {avatar.label}
                </span>
              </button>
            ))}
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <p className="text-red-400 text-sm text-center mb-4">{error}</p>
        )}

        {/* Continue Button */}
        <button
          onClick={handleContinue}
          className="w-full py-4 bg-gradient-to-r from-orange-500 to-amber-400 hover:from-orange-600 hover:to-amber-500 text-white font-bold text-lg rounded-xl transition-all duration-300 transform hover:scale-105 shadow-lg"
        >
          Continue
        </button>

        {/* Cancel Button */}
        <button
          onClick={onClose}
          className="w-full mt-3 py-3 bg-transparent hover:bg-white/10 text-white/70 hover:text-white font-medium rounded-xl transition-all duration-200"
        >
          Cancel
        </button>
      </div>
    </div>
  );
};

export default PlayerSetupModal;
